// TH14 synthetic training aliases used by this card (see transcribe/th14/touhou-bullets.ecl,
// bullet-types.md). Native type 0..23 -> modern same number; synthetic appearance mapping.
const TH14_RICE: int = 480;          // native type 8
const TH14_INVERT_RICE: int = 592;   // native type 15
const TH14_BIG_BALL: int = 640;      // native type 18

// th14_s5_b7 — TH14 v1.00b Stage 5 BossCard4, spell 80–83
// 源: st05bs.ecl.txt:867-962(入口) / 964-1054(BossCard4_at, at2) / 1056-1103(BossDead)
//     default.ecl.txt:130-146(Ecl_EtBreak2_ni)
// 卡帧0起算；卡帧约120建真实 Boss；源槽0的3000帧从894第二次timerReset起，
// 即源攻击到卡帧约3280；卡帧3280..3340走超时收尾闭包。

const TIME_LIMIT: int = 3784;       // 120开场 + 3660窗口 + 4启动余量
const OPENING_BUFFER: int = 120;
const BOSS_HP: int = 2700;          // 源 Boss 入口 lifeSet(2700)；无敌外壳不模拟DPS
const F0_STEP: int = 182;           // 源926 %F0=0.017453f rad ≈ 1° 的BAM整数

// 源982-989 弹0的EX链: ANIM(a=1,退位移4v) → VELTIME30→1.0 → SETSPRITE8 → VELTIME50→3.0
// → SETSPRITE15 → VELTIME60→2.0。ANIM退位移在出弹点用 sh_dist 表达；PLAYSOUND省略。
xformdef AT_RAMP {
    step_speed(1fx, 30);
    wait(30);
    set_sprite(TH14_RICE, 2);
    step_speed(3fx, 50);
    wait(50);
    set_sprite(TH14_INVERT_RICE, 2);
    step_speed(2fx, 60);
    wait(60);
}

// 源964-1013 BossCard4_at: 固定方向环(etAim 3)，7/12/14/14路、1层、速度2.0；
// 每2帧一发、60发后停120帧；每发基角加%F0（父循环随机翻号）。源%C/%D循环在本卡窗口内
// 等价于12个240帧周期（第13轮首发在源槽0时限之后）。
async sub at_task() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 14;                                   // 源977 !LO
    if rank == 0 { ways = 7; }                            // 源971 !E
    else if rank == 1 { ways = 12; }                      // 源973 !N
    sh_reset(0);
    sh_sprite(0, TH14_INVERT_RICE, 2);                    // 源969 etSprite(0,15,2)
    sh_ring(0, 1);
    sh_aim(0, 0);                                         // 源968 etAim(0,3) 固定方向环
    sh_count(0, ways, 1);                                 // 源979 etCount(0,-,1)
    sh_angle(0, 90deg, 0deg);                             // 源980 基角π/2；层偏1.875°在M=1不消费
    sh_speed(0, 2fx, 0fx);                                // 源981 etSpeed(0,2.0,1.0)，M=1取s0
    sh_dist(0, -8fx);                                     // 源982 ANIM a=1: position -= 4*velocity
    sh_xform(0, AT_RAMP);
    var base: angle = rand(65536) as angle;               // 源991 %A=%RANDRAD
    for cycle in 0..12 {
        for j in 0..60 {
            sh_angle(0, base, 0deg);                      // 源999 etAngle(0,%A,0)
            sh_fire(0);                                   // 源1005 etOn(0)
            base = base + (self_int(0) as angle);         // 源1001 %A+=%F0
            wait(2);                                      // 源1006
        }
        wait(120);                                        // 源1009
    }
}

// 源1015-1054 BossCard4_at2: 自机狙扇形(etAim 0)，1/1/3/5路×路间距45°、速度2.5；
// 首轮在wait(90)+%C后，随后每轮3发(间隔20帧)，%C>10时每轮减5。E的%C=180000在窗口内不发弹。
async sub at2_task() {
    var rank: int = global(GVAR_RANK);
    var ways: int = 5;                                    // 源1028 !LO
    if rank < 2 { ways = 1; }                             // 源1022-1025 !E/!N
    else if rank == 2 { ways = 3; }                       // 源1026 !H
    sh_reset(1);
    sh_sprite(1, TH14_BIG_BALL, 3);                       // 源1020 etSprite(1,18,3)
    sh_ring(1, 0);
    sh_aim(1, 1);                                         // 源1019 etAim(1,0) 自机狙扇形
    sh_count(1, ways, 1);                                 // 源1030 etCount(1,-,1)
    sh_angle(1, 0deg, 45deg);                             // 源1031 路间距0.7853982f
    sh_speed(1, 2.5fx, 0fx);                              // 源1032 etSpeed(1,2.5,1.0)，M=1取s0
    sh_dist(1, -10fx);                                    // 源1033 ANIM a=1: position -= 4*velocity
    wait(90);                                             // 源1034
    var sampled_rad: angle = rand(65536) as angle;        // 源1035 %A=%RANDRAD(后续未读，保留抽样点)
    var interval: int = 10;                               // 源1037 diffI($C,180000,180,100,10)
    if rank == 0 { interval = 180000; }
    else if rank == 1 { interval = 180; }
    else if rank == 2 { interval = 100; }
    var elapsed: int = 90;                                // 本任务已走帧数；2849 = 源槽0时限处
    while elapsed < 2849 {
        var w: int = interval;
        if elapsed + w > 2849 { w = 2849 - elapsed; }
        wait(w);                                          // 源1041
        elapsed = elapsed + w;
        var e: int = 3;                                   // 源1042 $E=3
        while e > 0 {
            if elapsed >= 2849 { e = 0; } else {
                sh_fire(1);                               // 源1045 etOn(1)
                e = e - 1;
                wait(20);                                 // 源1046
                elapsed = elapsed + 20;
            }
        }
        if interval > 10 { interval = interval - 5; }     // 源1049-1050
    }
}

// 源 default.ecl.txt:94-110 Ecl_EtBreak（源897 符卡开始时的扩张etCancel波浪）：
// 半径16→636、步长10、每帧一次；etCancel 转道具，故 stars=1。
async sub et_break_start() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var r: fx = 16fx;
    while r < 640fx {
        clear_bullets_at($self_x, $self_y, r, 1);
        r = r + 10fx;
        wait(1);
    }
}

// 源 default.ecl.txt:130-146 Ecl_EtBreak2_ni（超时退场路径）：以自身为中心的扩张etClear，
// 半径16→634、步长6、每帧一次。etClear不转道具，故 stars=0。
async sub et_break_ni() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    var r: fx = 16fx;
    while r < 640fx {
        clear_bullets_at($self_x, $self_y, r, 0);
        r = r + 6fx;
        wait(1);
    }
}

async sub boss_main() {
    // 源869-889 第一reset/清场/状态复位：独立卡无同敌旧async、旧弹、激光或上一段速度/插值；
    // etCancel(640)、spellEnd、funcSet(0)、laserCancel、moveVel/movePosTime(0)、MISS/BOMB/CAPTURE
    // 均无可写状态。anm/playSound/BossItemPhase 为表现与普通奖励，按共用取舍省略。
    // 源 Boss 公共入口框48/48 → 目标半径24；训练外壳整段无敌（源892 setInvuln(160) 不模拟DPS）
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(24fx);
    // 源891 movePosTime(60,4,0,128)，入口锚点(0,144)
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(160);                                            // 源892-893
    // 源894-908 第二timerReset/清场/槽0时限；源897 的 Ecl_EtBreak 清弹波浪保留
    spawn et_break_start();
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);               // 源914
    wait(150);                                            // 源915-927：t=60/120仅动画
    // 源922 moveLimit(0,192,280,128)：本段位置恒为(0,192)，60帧退场位移≤24px，不触边
    spawn at_task();                                      // 源924
    spawn at2_task();                                     // 源925
    set_self_int(0, F0_STEP);                             // 源926 %F0=+0.017453f（共享槽0的用途）
    // 源927-960 父循环：anm/playSound、$I0+funcCall(2)（画面操作，已批准省略）、
    // unknown567 置清SPELLCARD 0x100位（单独记录，不追消费者）均无可执行物理效果；
    // 保留每轮两处 $RAND%2 对F0的翻号
    for cycle in 0..4 {
        wait(190);                                        // 源929-936
        if rand(2) == 0 { set_self_int(0, -self_int(0)); }    // 源940-941
        wait(310);                                        // 源943-951
        if rand(2) == 0 { set_self_int(0, -self_int(0)); }    // 源955-956
        wait(180);                                        // 源958-959
    }
    wait(130);                                            // 到源槽0时限（rel3000，卡帧约3280）
    // 源 BossDead 1056-1103 超时路径：停发射后按收尾闭包清弹退场，不启动后继攻击
    move_vel(0, rand(65536) as angle, 0.4fx, EASE_LINEAR);    // 源1061
    _ = spawn_enemy($self_x, $self_y, 1, 0, 0, 0, et_break_ni);   // 源1066
    wait(60);                                             // 源1069
    clear_bullets_at($self_x, $self_y, 1024fx, 0);        // 源1070 etClearAll；道具按共用取舍省略
}

async sub attack() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 144fx, BOSS_HP, 0, 0, 0, boss_main);   // 入口位置锚点(0,144)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, attack, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(60); }
}
